public static <K, V> ImmutableMap<K, V> uniqueIndex(Iterator<V> values, Function<? super V, K> keyFunction) {
  checkNotNull(keyFunction);
  ImmutableMap.Builder<K, V> builder = ImmutableMap.builder();
  try {
    while (values.hasNext()) {
      V value = values.next();
      builder.put(keyFunction.apply(value), value);
    }
    return builder.build();
  } catch (UnsupportedOperationException | IllegalArgumentException | ClassCastException | NullPointerException | IllegalStateException e) {
    // Handle the exception, possibly rethrowing or logging it
    throw new RuntimeException("An error occurred while building the map.", e);
  }
}
